BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: medium / L2 — Tolerable misstatement vs. performance materiality in sampling
(1, 'Misstatements and Control Deficiencies', 'During the audit of Granite Peak Electronics, the engagement partner sets overall materiality at $400,000 and performance materiality at $280,000. When designing a sampling plan for inventory testing, the senior auditor proposes using a tolerable misstatement of $200,000 for the inventory account. Under AU-C 530, the tolerable misstatement used in audit sampling:', '["Must equal overall materiality for the financial statements as a whole", "Must equal performance materiality as defined by the engagement partner", "May be set at or below performance materiality for a particular class of transactions", "Should be set at twice the clearly trivial threshold to ensure adequate precision"]'::jsonb, 2, 'Under AU-C 530.A3, tolerable misstatement is the application of performance materiality to a particular sampling procedure. It may be set at or below performance materiality for the class of transactions being tested. Choice B is incorrect because tolerable misstatement need not equal performance materiality—it may be lower to account for undetected misstatements across multiple audit areas.', 'medium', 2),

-- Q2: hard / L3 — Qualitative factors in evaluating quantitatively immaterial misstatements
(1, 'Misstatements and Control Deficiencies', 'While auditing Cascade Medical Group, the auditor discovers an uncorrected $18,000 misclassification of officer compensation as consulting fees. Overall materiality is $750,000. The misstatement is quantitatively immaterial but may have SEC disclosure implications and could indicate a concealed related-party transaction. Under AU-C 450, the auditor should:', '["Accumulate the misstatement but conclude it is immaterial based on its dollar amount alone", "Evaluate qualitative factors including potential concealment of related-party transactions", "Require management to correct the misstatement only if it exceeds performance materiality", "Report the misstatement to the SEC before issuing the audit report"]'::jsonb, 1, 'AU-C 450.11 requires the auditor to evaluate both quantitative and qualitative factors when assessing uncorrected misstatements. A misstatement that is quantitatively immaterial may still be material due to qualitative factors such as potential concealment of related-party transactions or management intent. Choice A is incorrect because evaluating misstatements solely on dollar amount ignores the qualitative considerations required by the standard.', 'hard', 3),

-- Q3: easy / L1 — Definition of a control deficiency
(1, 'Misstatements and Control Deficiencies', 'What is a control deficiency in the context of an audit?', '["A shortcoming in internal control design or operation that prevents timely detection or prevention of misstatements", "A financial statement error caused by management fraud", "An incorrect accounting estimate based on faulty assumptions", "A disagreement between the auditor and management about a disclosure"]'::jsonb, 0, 'Under AU-C 265.07, a control deficiency exists when the design or operation of a control does not allow management or employees to prevent or detect misstatements on a timely basis. Choice B is incorrect because fraud is a separate concept—while control deficiencies may increase fraud risk, the deficiency itself is about the control shortcoming, not the resulting misstatement.', 'easy', 1),

-- Q4: medium / L3 — Timing of written communication of material weaknesses
(1, 'Misstatements and Control Deficiencies', 'During the audit of Redstone Manufacturing for the year ended December 31, 2025, the engagement team identifies a material weakness in the revenue recognition process on February 10, 2026. The audit report is expected to be issued on March 1, 2026. Under AU-C 265, the auditor should communicate this material weakness to those charged with governance:', '["Only after the audit report has been issued", "Within 30 calendar days of issuing the audit report", "At the auditor''s discretion, within one year of the audit completion", "In writing no later than 60 days following the report release date"]'::jsonb, 3, 'AU-C 265.13 requires the auditor to communicate significant deficiencies and material weaknesses in writing to those charged with governance no later than 60 days following the report release date. Choice A is incorrect because the standard does not require waiting until after the report is issued—early communication is permitted and often encouraged, though the written communication has a deadline tied to the report release date.', 'medium', 3),

-- Q5: medium / L2 — Management representation about uncorrected misstatements
(1, 'Misstatements and Control Deficiencies', 'At the conclusion of the audit of Birchwood Financial Corp., the engagement team has accumulated eight uncorrected misstatements on the summary schedule. The team is preparing to request a management representation letter. Under AU-C 450, the auditor should:', '["Omit immaterial misstatements from the summary provided to management", "Request that management provide a written representation acknowledging the uncorrected misstatements and their belief that the effects are immaterial", "Require management to correct all eight misstatements regardless of materiality", "Include only misstatements exceeding clearly trivial in the management representation letter"]'::jsonb, 1, 'AU-C 450.14 requires the auditor to request a written representation from management that it believes the effects of uncorrected misstatements are immaterial, individually and in the aggregate, to the financial statements as a whole. A summary of such items should be included in or attached to the representation. Choice A is incorrect because the auditor should communicate all accumulated uncorrected misstatements, not just those considered material.', 'medium', 2),

-- Q6: medium / L3 — Prior-period uncorrected misstatements rolling into current period
(1, 'Misstatements and Control Deficiencies', 'Silverline Logistics had $45,000 in uncorrected misstatements from the prior year that rolled forward into the current-year financial statements. During the current-year audit, the engagement team identifies an additional $30,000 in new uncorrected misstatements. Overall materiality is $100,000. When evaluating the aggregate effect, the auditor should:', '["Evaluate only the $30,000 in current-year misstatements since prior-year amounts were previously accepted", "Evaluate only the prior-year rollover since it was the first identified error", "Consider the combined $75,000 effect of both current and prior-year uncorrected misstatements on the current-period financial statements", "Disregard prior-year amounts unless they individually exceed performance materiality"]'::jsonb, 2, 'AU-C 450.12 requires the auditor to evaluate the aggregate effect of uncorrected misstatements, including the net effect of prior-period uncorrected misstatements on current-period financial statements. The cumulative $75,000 must be assessed against the $100,000 materiality threshold. Choice A is incorrect because prior-period misstatements that affect the current period cannot be ignored simply because they were previously accumulated.', 'medium', 3),

-- Q7: easy / L1 — Definition of uncorrected misstatement
(1, 'Misstatements and Control Deficiencies', 'What is an uncorrected misstatement?', '["A misstatement identified by the auditor that management has not corrected in the financial statements", "A mathematical error discovered after the audit report has been issued", "An accounting policy the auditor disagrees with but cannot change", "A disclosure omission that management intentionally excluded from footnotes"]'::jsonb, 0, 'Under AU-C 450.06, uncorrected misstatements are misstatements that the auditor has accumulated during the audit and that have not been corrected by management. The auditor accumulates these on a summary schedule for evaluation. Choice D is incorrect because while disclosure omissions can be misstatements, an uncorrected misstatement specifically refers to any identified misstatement management declines to adjust, not just intentional omissions.', 'easy', 1),

-- Q8: medium / L2 — Documentation requirements for misstatements
(1, 'Misstatements and Control Deficiencies', 'During the audit of Pinnacle Construction, the engagement team identifies 12 misstatements, 9 of which management corrects. The auditor is assembling the working papers. Under AU-C 450, the auditor''s documentation must include:', '["Only the three uncorrected misstatements since management corrected the remaining nine", "Only misstatements exceeding the clearly trivial threshold whether corrected or not", "A narrative explaining why each corrected misstatement was originally recorded incorrectly", "The clearly trivial threshold, all accumulated misstatements, and the basis for concluding whether uncorrected misstatements are material"]'::jsonb, 3, 'AU-C 450.15 requires the auditor to document the clearly trivial threshold, all misstatements accumulated during the audit (both corrected and uncorrected), and the conclusion on whether uncorrected misstatements are material individually or in the aggregate. Choice A is incorrect because documentation must include all accumulated misstatements, not just those remaining uncorrected, to provide a complete audit trail.', 'medium', 2),

-- Q9: easy / L2 — Distinguishing significant deficiency from material weakness
(1, 'Misstatements and Control Deficiencies', 'During the audit of Lakewood Distributors, the auditor identifies a control deficiency in the purchasing approval process. The deficiency is less severe than a material weakness but still important enough to merit attention by those charged with governance. Under AU-C 265, this deficiency is best classified as:', '["An inconsequential deficiency requiring no communication", "A significant deficiency in internal control", "A material weakness in internal control", "A reportable condition under GAGAS only"]'::jsonb, 1, 'AU-C 265.08 defines a significant deficiency as a deficiency, or combination of deficiencies, in internal control that is less severe than a material weakness yet important enough to merit attention by those charged with governance. Choice C is incorrect because a material weakness involves a reasonable possibility that a material misstatement will not be prevented or detected, which represents a higher severity threshold.', 'easy', 2),

-- Q10: hard / L4 — Evaluating remediation adequacy of previously reported material weakness
(1, 'Misstatements and Control Deficiencies', 'Clearwater Healthcare reported a material weakness in its revenue cycle controls during the prior-year audit. Management implemented a new automated three-way match system and hired additional accounts receivable staff. During the current-year audit, the engagement team tests the remediated controls for six months and finds two exceptions in 40 samples. Management asserts the weakness has been fully remediated. The auditor should:', '["Accept management''s assertion since the error rate of 5% is below a typical expected error rate", "Conclude the material weakness is remediated because management implemented both automated and manual controls", "Evaluate whether the remediated controls operated effectively for a sufficient period and whether the exceptions indicate the new design is inadequate", "Automatically reclassify the material weakness as a significant deficiency based on the reduced error rate"]'::jsonb, 2, 'Under AU-C 265.A14, the auditor must evaluate whether remediated controls have been designed properly and have operated effectively for a sufficient period. Two exceptions in 40 samples may or may not indicate ongoing issues depending on the nature and cause of the exceptions. Choice D is incorrect because control deficiency severity is not mechanically reclassified based on error rates—the auditor must evaluate the nature, cause, and potential magnitude of misstatements that could result.', 'hard', 4),

-- Q11: hard / L4 — Fraud risk indicators in accumulated misstatements
(1, 'Misstatements and Control Deficiencies', 'While auditing Thornfield Industries, the engagement team accumulates five uncorrected misstatements totaling $42,000 against materiality of $200,000. Four of the five misstatements increase reported revenue, each originating from manual journal entries posted by the same senior accountant on the last day of each quarter. Under AU-C 240 and AU-C 450, the auditor should:', '["Reconsider whether the misstatements may indicate fraud, reassess audit risk, and evaluate the need for additional procedures", "Conclude the misstatements are immaterial and note the pattern for next year''s planning", "Require management to terminate the senior accountant before issuing the audit opinion", "Report the pattern directly to law enforcement as suspected embezzlement"]'::jsonb, 0, 'AU-C 240.35 requires the auditor to evaluate whether identified misstatements may be indicative of fraud. When a pattern of misstatements suggests intentional manipulation—such as consistent revenue overstatement via manual entries by one individual—the auditor must reconsider the risk assessment and determine whether additional procedures are necessary. Choice B is incorrect because even quantitatively immaterial misstatements must be evaluated for fraud indicators regardless of dollar amount.', 'hard', 4),

-- Q12: medium / L3 — Management refusing to include uncorrected misstatements in representation letter
(1, 'Misstatements and Control Deficiencies', 'The audit of Westbury Publishing is nearing completion. The engagement team has accumulated $28,000 in uncorrected misstatements against performance materiality of $150,000. The CFO is willing to sign the representation letter but wants to remove the sentence acknowledging the uncorrected misstatements. Under AU-C 450 and AU-C 580, the auditor should:', '["Accept the modified representation letter since the misstatements are below performance materiality", "Issue a qualified opinion due to the resulting scope limitation", "Withdraw from the engagement and notify regulators immediately", "Explain that the representation is required and evaluate the refusal as a potential scope limitation if management persists"]'::jsonb, 3, 'AU-C 580.20 states that if management does not provide one or more of the requested written representations, the auditor should discuss the matter with management. If management still refuses, the auditor must evaluate the implications, which may constitute a scope limitation affecting the audit opinion. Choice A is incorrect because the management representation requirement is not waived based on the dollar amount of uncorrected misstatements.', 'medium', 3),

-- Q13: medium / L2 — Clearly trivial threshold application
(1, 'Misstatements and Control Deficiencies', 'The audit engagement team for Juniper Creek Retail establishes overall materiality at $500,000 and performance materiality at $350,000. The senior auditor proposes setting the clearly trivial threshold at $25,000. During testing, the team identifies a $22,000 misstatement in prepaid expenses. Under AU-C 450, this misstatement:', '["Must be accumulated on the summary of uncorrected misstatements because it exceeds 5% of materiality", "Must be communicated to those charged with governance as a significant deficiency", "Need not be accumulated because it falls below the clearly trivial threshold", "Must be corrected by management before the audit report can be issued"]'::jsonb, 2, 'AU-C 450.05 states that the auditor need not accumulate misstatements that are clearly trivial. Since the $22,000 misstatement is below the $25,000 clearly trivial threshold, it need not be accumulated on the summary of uncorrected misstatements. Choice A is incorrect because the accumulation threshold is not a fixed percentage of materiality—it is the clearly trivial amount set by the auditor based on professional judgment.', 'medium', 2),

-- Q14: hard / L4 — IT general control deficiency cascading to dependent application controls
(1, 'Misstatements and Control Deficiencies', 'While auditing Northstar Financial, the IT auditor discovers that the company''s change management process for its ERP system lacks proper segregation of duties—developers can promote code changes to production without independent approval. Several automated application controls in the revenue and purchasing modules depend on ERP system integrity. No exceptions were found in application control testing. Under AU-C 265 and AU-C 315, the auditor should:', '["Conclude the application controls are effective since no exceptions were found in direct testing", "Evaluate the IT general control deficiency as potentially affecting all dependent automated controls and assess whether it constitutes a material weakness", "Report the deficiency only to IT management since it is an operational rather than financial reporting issue", "Limit the finding to a significant deficiency because no actual misstatements were detected"]'::jsonb, 1, 'Under AU-C 315.A142, IT general controls support the continued proper operation of application controls. A deficiency in change management that allows unauthorized code changes could undermine the reliability of all dependent automated controls. Choice D is incorrect because the severity of a control deficiency is assessed based on the magnitude of potential misstatement, not whether actual misstatements were detected—an IT general control failure could affect the entire population of automated transactions.', 'hard', 4),

-- Q15: medium / L3 — Communication timing: interim oral vs. written deadline
(1, 'Misstatements and Control Deficiencies', 'During the audit of Maple Ridge Community Bank, the engagement team identifies a material weakness in the loan loss reserve estimation process on January 15, 2026. The audit report is scheduled for release on March 1, 2026. The audit committee chair requests that the auditor delay the written communication until the annual board meeting on April 15, 2026. Under AU-C 265, the auditor:', '["May communicate the material weakness orally on an interim basis but must provide the required written communication no later than 60 days after the report release date", "Must wait until April 15 as requested by the audit committee", "Must provide the written communication before issuing the audit report on March 1", "May skip written communication entirely if oral communication was provided timely"]'::jsonb, 0, 'AU-C 265.13 requires written communication of significant deficiencies and material weaknesses no later than 60 days following the report release date. While the auditor is encouraged to communicate on a timely basis, interim oral communication is acceptable, provided written communication follows within the 60-day window. Choice C is incorrect because the standard does not require written communication before the report is issued—the deadline is tied to the report release date.', 'medium', 3),

-- Q16: medium / L3 — Evaluating directional bias in uncorrected misstatements
(1, 'Misstatements and Control Deficiencies', 'During the audit of Cornerstone Enterprises, the engagement team identifies six uncorrected misstatements, each between $3,000 and $5,000, all of which understate expense accounts. Overall materiality is $250,000, and the aggregate uncorrected amount is $24,000. The auditor notes that all six misstatements favor reported earnings. Under AU-C 450, the auditor should:', '["Conclude the misstatements are immaterial since $24,000 is well below $250,000 and issue an unmodified opinion", "Require management to correct all six misstatements to eliminate any audit risk", "Adjust the clearly trivial threshold downward so future small misstatements are captured", "Consider whether the consistent bias toward overstating earnings indicates a risk of management bias and evaluate whether additional procedures are warranted"]'::jsonb, 3, 'AU-C 450.A18 requires the auditor to consider whether uncorrected misstatements may indicate a bias in management''s judgments. When all misstatements move in the same direction—understating expenses to inflate earnings—this pattern may signal intentional management bias. Choice A is incorrect because even when the aggregate amount is below materiality, a directional pattern requires the auditor to evaluate the risk of management bias and potentially expand procedures.', 'medium', 3),

-- Q17: easy / L1 — Three types of misstatements under AU-C 450
(1, 'Misstatements and Control Deficiencies', 'What are the three types of misstatements identified in AU-C 450?', '["Factual misstatements, judgmental misstatements, and projected misstatements", "Intentional misstatements, unintentional misstatements, and systemic misstatements", "Material misstatements, immaterial misstatements, and trivial misstatements", "Quantitative misstatements, qualitative misstatements, and disclosure misstatements"]'::jsonb, 0, 'AU-C 450.A1–A3 identifies three types of misstatements: factual (no doubt about the error), judgmental (arising from management''s unreasonable estimates or accounting policy selections), and projected (the auditor''s best estimate of misstatement in a population based on sample results). Choice B is incorrect because the standard categorizes misstatements by their nature and origin, not by whether they are intentional or unintentional.', 'easy', 1),

-- Q18: easy / L1 — Who establishes materiality for the audit
(1, 'Misstatements and Control Deficiencies', 'In the context of evaluating misstatements, who is responsible for establishing materiality levels for the audit?', '["Management of the audited entity", "The auditor based on professional judgment", "Those charged with governance", "The applicable regulatory body"]'::jsonb, 1, 'Under AU-C 320.09, the auditor is responsible for determining materiality for the financial statements as a whole when establishing the overall audit strategy. This determination is a matter of the auditor''s professional judgment. Choice A is incorrect because while management may have its own internal thresholds, the auditor independently determines materiality for audit planning and evaluation purposes.', 'easy', 1),

-- Q19: medium / L2 — Misstatement from fictitious inventory tags indicating possible fraud
(1, 'Misstatements and Control Deficiencies', 'During the audit of Valley Forge Pharmaceuticals, the auditor detects a $60,000 overstatement in finished goods inventory caused by fictitious inventory tags at a remote warehouse. Overall materiality is $2,000,000. The warehouse manager claims the tags were entered accidentally. Under AU-C 240 and AU-C 450, the auditor should:', '["Accept the explanation and accumulate the $60,000 as an uncorrected misstatement since it is below materiality", "Report the finding to local law enforcement before performing additional procedures", "Evaluate the misstatement as a potential indicator of fraud, consider the implications for the risk assessment, and determine whether additional procedures are needed", "Remove the warehouse from the audit scope to avoid further complications"]'::jsonb, 2, 'AU-C 240.35–.36 requires the auditor to evaluate whether a misstatement may be the result of fraud. Fictitious inventory tags raise significant fraud concerns regardless of dollar amount. The auditor must reconsider the risk assessment and determine whether additional procedures are warranted. Choice A is incorrect because a potentially fraudulent misstatement cannot simply be accumulated as a routine uncorrected item without further investigation into its nature and implications.', 'medium', 2),

-- Q20: hard / L4 — Evaluating qualitative materiality of near-threshold misstatement in sensitive area
(1, 'Misstatements and Control Deficiencies', 'Apex Financial Advisors has overall materiality set at $300,000. The auditor accumulates uncorrected misstatements totaling $265,000, consisting of three errors in the bonus accrual that reduce executive compensation expense and increase net income by 4%. Management refuses to correct them, arguing they are below materiality. The audit committee has expressed concern about executive pay transparency. Under AU-C 450, the auditor should:', '["Accept management''s position since $265,000 is below the $300,000 materiality threshold", "Reduce materiality to $265,000 to ensure the misstatements are captured", "Communicate the uncorrected misstatements to the audit committee and issue an unmodified opinion", "Evaluate whether the proximity to materiality combined with the qualitative sensitivity of executive compensation disclosures warrants a modified opinion"]'::jsonb, 3, 'AU-C 450.11 requires both quantitative and qualitative evaluation. When uncorrected misstatements approach materiality (88% of threshold) and involve qualitatively sensitive areas like executive compensation—especially when governance has flagged transparency concerns—the auditor must evaluate whether users'' decisions could be influenced. Choice A is incorrect because the standard does not treat materiality as a bright-line threshold; misstatements approaching materiality with significant qualitative factors may still be material.', 'hard', 4),

-- Q21: easy / L1 — Purpose of the summary of uncorrected misstatements
(1, 'Misstatements and Control Deficiencies', 'What is the primary purpose of the auditor''s summary of uncorrected misstatements?', '["To evaluate whether uncorrected misstatements are material individually or in the aggregate", "To determine the amount of the auditor''s fee adjustment", "To establish the entity''s internal control rating", "To calculate the tax liability for the current year"]'::jsonb, 0, 'Under AU-C 450.10, the auditor accumulates identified misstatements to evaluate whether uncorrected misstatements are material, individually or in the aggregate, to the financial statements as a whole. This evaluation directly affects the audit opinion. Choice C is incorrect because the summary of uncorrected misstatements relates to financial statement accuracy, not to rating or scoring the entity''s internal control system.', 'easy', 1),

-- Q22: easy / L1 — Deficiency in design vs. deficiency in operation
(1, 'Misstatements and Control Deficiencies', 'What distinguishes a deficiency in the design of a control from a deficiency in its operation?', '["A design deficiency involves employee error while an operating deficiency involves system error", "A design deficiency occurs only in automated controls while an operating deficiency occurs only in manual controls", "A design deficiency means the control is missing or improperly designed, while an operating deficiency means a properly designed control does not operate as intended", "A design deficiency always results in a material weakness while an operating deficiency results in a significant deficiency"]'::jsonb, 2, 'AU-C 265.07 distinguishes between design and operation deficiencies. A design deficiency exists when a necessary control is missing or not designed to meet the control objective. An operating deficiency exists when a properly designed control does not operate effectively. Choice D is incorrect because neither type automatically constitutes a material weakness or significant deficiency—severity depends on the magnitude of potential misstatement.', 'easy', 1),

-- Q23: medium / L2 — Communication of lesser deficiencies (not sig def or MW)
(1, 'Misstatements and Control Deficiencies', 'During the audit of Ridgeway Municipal Services, the engagement team identifies several internal control deficiencies that are neither significant deficiencies nor material weaknesses. The engagement partner discusses whether to communicate these findings. Under AU-C 265, control deficiencies that are not significant deficiencies or material weaknesses:', '["Must never be communicated to management to avoid unnecessary alarm", "May be communicated orally or in writing to management at the appropriate level", "Must be communicated in writing to those charged with governance within 60 days", "Must be reported to the governmental regulatory body overseeing the entity"]'::jsonb, 1, 'AU-C 265.A25 permits the auditor to communicate control deficiencies that are not significant deficiencies or material weaknesses to management at an appropriate level, either orally or in writing. This communication is discretionary rather than required. Choice C is incorrect because the 60-day written communication requirement applies only to significant deficiencies and material weaknesses, not to lesser control deficiencies.', 'medium', 2),

-- Q24: hard / L4 — Aggregation of deficiencies across multiple transaction cycles
(1, 'Misstatements and Control Deficiencies', 'The audit of Meridian Health Systems reveals three separate control deficiencies: (1) the revenue cycle lacks an independent reconciliation of cash receipts, (2) the payroll department does not verify hours against approved timecards, and (3) the IT department has no access log review for the general ledger system. Each deficiency alone is assessed as a significant deficiency. Management argues they are unrelated. Under AU-C 265, the auditor should:', '["Accept management''s position and report three separate significant deficiencies", "Combine all three into a single material weakness because they exist in the same entity", "Evaluate only the largest deficiency and disclose the others as incidental findings", "Assess whether the deficiencies combined create a reasonable possibility that a material misstatement will not be prevented or detected, potentially constituting a material weakness"]'::jsonb, 3, 'AU-C 265.A12 requires the auditor to consider whether a combination of control deficiencies might constitute a significant deficiency or material weakness. Overlapping weaknesses across revenue, payroll, and IT access controls could create a systemic gap in the control environment. Choice A is incorrect because the standard explicitly requires the auditor to consider the interaction and aggregation of deficiencies rather than evaluating each in isolation.', 'hard', 4),

-- Q25: medium / L3 — Entity-level control deficiency vs. transaction-level effectiveness
(1, 'Misstatements and Control Deficiencies', 'During the audit of Harbor Light Properties, the auditor discovers that the board of directors has not met in 14 months and has not reviewed any financial reports. At the transaction level, the accounts payable and receivable controls are operating effectively with no exceptions noted. Under AU-C 265, the auditor should:', '["Evaluate the board''s oversight failure as an entity-level deficiency that may undermine the control environment despite effective transaction-level controls", "Conclude the controls are effective because transaction-level testing showed no exceptions", "Report only the transaction-level results since they are directly tied to financial statement assertions", "Issue a disclaimer of opinion due to the prolonged governance failure"]'::jsonb, 0, 'Under AU-C 265.A8, entity-level controls—including the governance structure and oversight by those charged with governance—affect the overall control environment and the effectiveness of other controls. A 14-month lapse in board oversight is a serious entity-level deficiency. Choice B is incorrect because effective transaction-level controls do not compensate for a fundamental breakdown in entity-level oversight, which could undermine the entire control environment.', 'medium', 3),

-- Q26: medium / L2 — Evaluating misstatements individually and in the aggregate
(1, 'Misstatements and Control Deficiencies', 'During the audit of Eastport Trading, the auditor identifies three uncorrected misstatements: a $40,000 overstatement of revenue, a $35,000 understatement of cost of goods sold, and a $20,000 overstatement of accounts receivable. Overall materiality is $120,000. Which statement best describes the auditor''s evaluation responsibility under AU-C 450?', '["Each misstatement should be evaluated independently, and since none exceeds $120,000, all are immaterial", "The auditor must evaluate the misstatements both individually and in the aggregate, considering their combined effect on the financial statements", "Only the revenue misstatement is relevant because it is the largest single item", "The auditor should average the three misstatements and compare the average to materiality"]'::jsonb, 1, 'AU-C 450.10–.11 requires the auditor to determine whether uncorrected misstatements are material, individually or in the aggregate. The combined directional effect on income ($40,000 revenue overstatement plus $35,000 COGS understatement) must be evaluated against materiality. Choice A is incorrect because evaluating misstatements only individually ignores their cumulative impact, which is explicitly required by the standard.', 'medium', 2),

-- Q27: easy / L1 — Preventive vs. detective controls
(1, 'Misstatements and Control Deficiencies', 'What is the difference between preventive controls and detective controls?', '["Preventive controls are automated while detective controls are always manual", "Preventive controls apply only to revenue while detective controls apply only to expenses", "Preventive controls stop errors before they occur, while detective controls identify errors after they have occurred", "Preventive controls are required by law while detective controls are optional"]'::jsonb, 2, 'Under AU-C 315.A77, preventive controls are designed to avert errors or irregularities from occurring, such as authorization requirements before processing transactions. Detective controls identify misstatements after they have occurred, such as account reconciliations. Choice A is incorrect because both preventive and detective controls can be either automated or manual—the distinction is based on timing relative to the transaction, not the method of execution.', 'easy', 1),

-- Q28: medium / L2 — Auditor requesting management to correct all misstatements
(1, 'Misstatements and Control Deficiencies', 'The audit of Pacific Coast Engineering reveals seven misstatements totaling $85,000. Management corrects four totaling $52,000 but declines to correct the remaining three totaling $33,000, citing immateriality. Overall materiality is $200,000. Under AU-C 450, the auditor should:', '["Accept management''s partial corrections and issue a qualified opinion for the $33,000 remaining", "Conclude the audit cannot be completed until all seven misstatements are corrected", "Reduce the overall materiality to $33,000 to match the remaining uncorrected amount", "Request management to correct all identified misstatements, and if management refuses, obtain an understanding of the reasons and evaluate whether uncorrected misstatements are material"]'::jsonb, 3, 'AU-C 450.07–.08 requires the auditor to communicate all accumulated misstatements to the appropriate level of management and request correction. If management declines, the auditor must understand management''s reasons and evaluate whether the uncorrected misstatements are material individually or in aggregate. Choice A is incorrect because a qualified opinion is not automatically required—the auditor must first evaluate materiality and determine the appropriate opinion modification, if any.', 'medium', 2),

-- Q29: medium / L3 — Evaluating compensating control mitigating a segregation of duties deficiency
(1, 'Misstatements and Control Deficiencies', 'Sterling Aerospace''s segregation of duties in the purchasing department is inadequate because the purchasing agent can both create purchase orders and approve invoices for payment. However, the controller performs a detailed monthly review of all purchases over $10,000 and investigates discrepancies. The auditor is evaluating the severity of the segregation of duties deficiency. Under AU-C 265, the auditor should:', '["Evaluate whether the controller''s monthly review effectively mitigates the risk created by the segregation of duties deficiency before concluding on severity", "Automatically classify the deficiency as a material weakness because segregation of duties failures are always material", "Ignore the compensating control because it is performed by a different employee", "Report the segregation of duties deficiency without considering the compensating control"]'::jsonb, 0, 'AU-C 265.A11 indicates that the auditor should consider compensating controls when evaluating the severity of a control deficiency. If the controller''s monthly review effectively mitigates the risk that unauthorized or erroneous purchases could cause material misstatement, the severity may be reduced. Choice B is incorrect because no category of control deficiency is automatically classified as a material weakness—the auditor must evaluate considering all relevant controls, including compensating ones.', 'medium', 3),

-- Q30: easy / L1 — Purpose of AU-C 450
(1, 'Misstatements and Control Deficiencies', 'What is the primary objective of AU-C Section 450, Evaluation of Misstatements Identified During the Audit?', '["To establish the rules for calculating performance materiality", "To guide the auditor in evaluating identified misstatements and their effect on the financial statements", "To define the procedures for testing internal controls", "To outline the requirements for communicating with management about fees"]'::jsonb, 1, 'AU-C 450.03 states that the objective of the auditor is to evaluate the effect of identified misstatements on the audit and the effect of uncorrected misstatements on the financial statements. This standard governs how the auditor accumulates, communicates, and evaluates misstatements. Choice A is incorrect because performance materiality is addressed in AU-C 320, not AU-C 450, although the two standards work together in practice.', 'easy', 1)
;

COMMIT;
